let state=defaultState(), storageMode='Starting…', db=null, saveTimer=null;
let ui={route:'dashboard',day:'d1',tab:'overview',week:1,lab:'tensor',labView:'explore',search:'',flow:'base',projectOpen:1,filter:'all',customEditing:null};
let timer={remaining:1500,total:1500,running:false,deadline:0,day:null,interval:null,completedSessions:0};let pyRunner=null,pyRunnerTimeout=null;
const E = s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
