const dayState=id=>state.days[id]||(state.days[id]={learned:false,steps:[false,false,false,false,false],quizPassed:false,quizDraft:{},quizHistory:[],quizLast:null,choice:null,wrong:0,manualComplete:false,readingsStatus:{},notes:'',bookmarked:false,completedAt:null});
const projectState=id=>state.projects[id]||(state.projects[id]={tasks:[false,false,false,false],notes:'',evidence:''});
const dayParts=id=>{const x=dayState(id);return [!!x.learned,x.steps.length>=5&&x.steps.every(Boolean),!!x.quizPassed]};
const done=id=>!!dayState(id).manualComplete||dayParts(id).every(Boolean);
const weekDone = number=>WEEKS[number-1].days.filter(d=>done(d.id)).length;
