async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Code copied to clipboard');return}const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.left='-9999px';document.body.appendChild(field);field.focus();field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw new Error('copy not supported');toast('Code copied to clipboard')}catch(err){toast('Clipboard blocked. Select and copy the code manually.')}}
function exportState(){const data=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);const blob=new Blob([data],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='form-ai-progress-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Your progress backup is downloading')}
function advanceDay(id,delta){const day=ALL_DAYS.find(d=>d.id===id);if(!day)return;const n=day.number+delta;if(n>=1&&n<=63)navigate('learn',{day:'d'+n})}
let audioCtx=null;
function playCompletionSound(){if(!state.settings.focusSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!audioCtx)audioCtx=new Audio();audioCtx.resume?.().catch(()=>{});const t=audioCtx.currentTime;
 for(const [i,freq] of [740,980,740].entries()){const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain(),start=t+i*.19;oscillator.type='sine';oscillator.frequency.setValueAtTime(freq,start);gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(0.17,start+.03);gain.gain.exponentialRampToValueAtTime(0.0001,start+.17);oscillator.connect(gain).connect(audioCtx.destination);oscillator.start(start);oscillator.stop(start+.18)}}catch(e){console.warn('Sound unavailable:',e)}}
function focusSeconds(){return (state.settings?.focusMinutes||25)*60}
function saveFocusSession(){state.focusSession={remaining:timer.remaining,total:timer.total,deadline:timer.deadline,running:timer.running,day:timer.day||ui.day};save()}
function restoreFocus(){timer.total=focusSeconds();timer.remaining=timer.total;const stored=state.focusSession;if(!stored)return;timer.total=stored.total;timer.remaining=stored.remaining;timer.day=stored.day;timer.deadline=stored.deadline;timer.running=stored.running;if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.deadline-Date.now())/1000));if(timer.remaining===0)finishFocus(false)}}
function finishFocus(sound=true){if(!timer.running&&timer.remaining!==0)return;timer.running=false;timer.remaining=0;const minutes=Math.round(timer.total/60),day=timer.day||ui.day;state.minutes[day]=(state.minutes[day]||0)+minutes;recordActivity('focus',day);state.focusSession=null;save();if(sound)playCompletionSound();toast(`Focus complete · ${minutes} minutes recorded`);if(['dashboard','analytics','notebook'].includes(ui.route))render();updateTimerUI()}
function focusToggle(){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.deadline-Date.now())/1000));timer.running=false;toast('Focus session paused')}else{if(timer.remaining<=0||timer.remaining>timer.total){timer.total=focusSeconds();timer.remaining=timer.total}timer.deadline=Date.now()+timer.remaining*1000;timer.day=timer.day||ui.day;timer.running=true;if(state.settings.focusSound){try{const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){if(!audioCtx)audioCtx=new Audio();audioCtx.resume?.().catch(()=>{})}}catch{}}toast(`${Math.ceil(timer.remaining/60)}-minute focus session started`)}saveFocusSession();updateTimerUI()}
function focusReset(){timer.running=false;timer.total=focusSeconds();timer.remaining=timer.total;timer.day=null;timer.deadline=0;state.focusSession=null;save();updateTimerUI();toast('Focus timer reset')}
function startTimerTicker(){if(timer.interval)clearInterval(timer.interval);timer.interval=setInterval(()=>{if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.deadline-Date.now())/1000));if(timer.remaining===0)finishFocus(true)}updateTimerUI()},650)}
function updateTimerUI(){const mm=String(Math.floor(timer.remaining/60)).padStart(2,'0'),ss=String(timer.remaining%60).padStart(2,'0');const label=document.getElementById('timerLabel');if(label)label.textContent=`${mm}:${ss}`;const dialFill=document.getElementById('timerDialFill');if(dialFill){const total=timer.total||focusSeconds(),fr=total>0?Math.max(0,Math.min(1,timer.remaining/total)):0;dialFill.style.strokeDashoffset=String((97.39*(1-fr)).toFixed(2));document.getElementById('timerDial')?.classList.toggle('active',timer.running||fr>0)}const toggle=document.getElementById('timerToggle');if(toggle){const running=timer.running,resumed=!running&&timer.remaining!==timer.total&&timer.remaining>0;toggle.classList.toggle('running',running);const verb=running?'Pause':resumed?'Resume':'Start';toggle.title=`${verb} focus session`;toggle.setAttribute('aria-label',`${verb} focus timer`)}
const fill=document.getElementById('timerProgress'),track=document.getElementById('timerProgressTrack');if(fill&&track){const total=timer.total||focusSeconds(),pct=timer.remaining<=0?100:Math.max(0,Math.min(100,Math.round((total-timer.remaining)/total*100)));fill.style.width=pct+'%';track.setAttribute('aria-valuenow',String(pct));track.classList.toggle('active',timer.running||pct>0||timer.remaining===0&&timer.total!==focusSeconds())}
const live=document.getElementById('studyTimeStat');if(live)live.textContent=`${minutesAll()+(timer.running?Math.max(0,Math.floor((timer.total-timer.remaining)/60)-(timer.loggedMin||0)):0)} min`;for(const sid of ['studyTimeStat','sessionTimeStat']){const el=document.getElementById(sid);if(el)el.textContent=`${minutesAll()+Math.max(0,Math.floor((timer.total||focusSeconds())-timer.remaining)/60-(timer.loggedMin||0))} min`}
}
function renderSearchResults(){const q=ui.search.toLowerCase().trim(),found=q?ALL_DAYS.filter(d=>(d.title+' '+d.explanation+' '+d.practice+' '+WEEKS[d.week-1].title).toLowerCase().includes(q)):[];return q?`${found.length?found.slice(0,40).map(d=>`<div class="search-result"><div><span class="upper">W${d.week} · DAY ${d.number}</span><div class="strong">${E(d.title)}</div><p class="sm muted" style="margin:4px 0">${E(d.explanation.slice(0,160))}</p></div><button class="btn btn-sm" data-action="open-day" data-day="${d.id}">Open ${I('arrow-right')}</button></div>`).join(''):`<div class="empty">No lessons match “${E(ui.search)}”. Try a broader term.</div>`}`:`<div class="empty">Try searching: <b>gradient</b>, <b>attention</b>, <b>LoRA</b>, <b>forgetting</b>, or <b>model registry</b>.</div>`}
function renderSearch(){return `${pageHead('Find knowledge','Search the curriculum','Find terms in all 63 daily lessons and their practice instructions. This search runs entirely in your browser.')}
<div class="card padded"><label class="upper" for="course-search">Search topics, concepts or tasks</label><input class="field" id="course-search" data-input="search" type="search" value="${E(ui.search)}" placeholder="e.g. gradient descent, tokenizer, LoRA" style="margin:12px 0" autocomplete="off"><div id="searchResults">${renderSearchResults()}</div></div>`}
NAV.splice(3,0,['search','Search lessons','search']);

function labCopyCode(){return defaultLabCode(currentLab())}
function fullCodeForDay(id,mode){const d=ALL_DAYS.find(x=>x.id===id);if(!d)return '';const base=SNIPPETS[id]||'';if(mode==='challenge')return CHALLENGES[id]||base;if(mode==='evidence')return `# Day ${d.number} notebook checklist\n# 1. ${d.practice}\n# 2. ${d.practiceIdeas[1][1]}\n# 3. ${d.practiceIdeas[2][1]}`;return base}
function resetLab(){const lab=currentLab();for(const key of (lab.controls||[]).map(x=>x[0]))delete state.labValues[key];const native={tensor:['tensorDims'],gradient:['gradLR','gradSteps'],tokenizer:['tokenText','tokenMode'],attention:['a1','a2','a3'],lora:['loraIn','loraOut','loraRank'],forgetting:['oldBefore','oldAfter','newBefore','newAfter']};for(const key of native[lab.id]||[])delete state.labValues[key];if(lab.id.startsWith('custom-'))for(const suffix of ['x','a','b'])delete state.labValues[`custom_${lab.id}_${suffix}`];save();render();toast('Lab controls restored to initial values')}
function quizSubmit(id){const d=ALL_DAYS.find(x=>x.id===id),s=dayState(id);if(!d||quizLimitReached(id))return;const answers=d.questions.map((_,i)=>s.quizDraft?.[i]);if(!answers.every(Number.isInteger)){toast('Answer all four questions first');return}const score=d.questions.filter((q,i)=>q.correct===answers[i]).length,attempt={score,total:4,passed:score>=3,answers,date:new Date().toISOString()};ui.tab='results';changeDay(id,item=>{item.quizHistory=[...(item.quizHistory||[]),attempt].slice(-50);item.quizLast=attempt;item.quizPassed=item.quizPassed||attempt.passed;item.quizDraft={};if(!attempt.passed)item.wrong=(item.wrong||0)+1},'quiz');toast(attempt.passed?`Quiz passed · ${score}/4`:`Quiz result · ${score}/4. Review your answers.`)}
function quizClear(id){if(!confirm('Reset quiz attempts, best score and mastery for this day? Your other learning milestones and notes are kept.'))return;ui.tab='quiz';changeDay(id,item=>{item.quizHistory=[];item.quizLast=null;item.quizPassed=false;item.quizDraft={};item.choice=null;item.wrong=0},'revision')}
function saveCustomLab(form){const f=new FormData(form),title=String(f.get('title')||'').trim().slice(0,75),desc=String(f.get('desc')||'').trim().slice(0,500),variable=String(f.get('variable')||'x').trim().slice(0,40),min=Number(f.get('min')),max=Number(f.get('max')),step=Number(f.get('step')),start=Number(f.get('start'));
 if(!title||!desc||!variable||!Number.isFinite(min)||!Number.isFinite(max)||!Number.isFinite(step)||!Number.isFinite(start)||max<=min||step<=0||max-min>100000||step>max-min||start<min||start>max){toast('Please provide a valid title, description and finite input range.');return}
 const old=state.customLabs.find(l=>l.id===ui.customEditing);if(!old&&state.customLabs.length>=40){toast('Maximum 40 custom labs. Remove one before creating another.');return}
 const id=old?.id||`custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;const lab={id,title,desc,variable,min,max,step,start,week:ui.customWeek||old?.week||1,formula:ui.customFormula||old?.formula||'linear',icon:'flask-conical'};
 if(old)Object.assign(old,lab);else state.customLabs.push(lab);
 ui.customEditing=null;ui.lab=id;ui.labView='explore';ui.customFormula=null;ui.customWeek=null;recordActivity('custom-lab',id);save();render();toast(old?'Custom lab updated':'Custom lab saved on this device')
}
function generatedCustomPython(lab){const f={linear:'a*x + b',quadratic:'a*x*x + b',sigmoid:'1/(1+math.exp(-(a*x+b)))',memory:'x*a*b/8/1e9',loss:'(a*x-b)**2'}[lab.formula]||'a*x+b';return `# ${lab.title}\nimport math\nx=${lab.start}\na=1.0\nb=0.0\ny=${f}\nprint({'input':x,'output':y})`}
function stopPython(){if(pyRunner){pyRunner.terminate();pyRunner=null}if(pyRunnerTimeout){clearTimeout(pyRunnerTimeout);pyRunnerTimeout=null}const out=document.getElementById('pythonOutput');if(out)out.textContent='Execution stopped. You can retry or copy the code to a local notebook.'}
function runPythonCell(){const lab=currentLab();const code=state.labCode[lab.id]??defaultLabCode(lab);stopPython();const out=document.getElementById('pythonOutput');
 if(/(?:^|\n)\s*(?:import\s+(?:torch|transformers|peft|tensorflow)\b|from\s+(?:torch|transformers|peft|tensorflow)\b)/.test(code)){
   if(out)out.textContent='This code requires packages not included in the optional browser Python environment (for example PyTorch). Copy the code into local Jupyter or another suitable Python environment instead.';
   return;
 }
 if(out)out.textContent='Loading optional Python/NumPy runtime… first run may download several MB.';
 const workerScript=`self.onmessage=async(event)=>{const code=event.data.code;let out=[];try{importScripts('https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js');const py=await loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.7/full/'});await py.loadPackage('numpy');py.setStdout({batched:s=>out.push(String(s))});py.setStderr({batched:s=>out.push(String(s))});await py.runPythonAsync(code);self.postMessage({ok:true,output:out.join('\\n').slice(0,30000)||'(Cell finished without printed output)'})}catch(err){self.postMessage({ok:false,output:(out.join('\\n')+'\\n'+String(err)).slice(0,30000)})}}`;
 try{const blob=new Blob([workerScript],{type:'text/javascript'}),url=URL.createObjectURL(blob);pyRunner=new Worker(url);URL.revokeObjectURL(url);pyRunner.onmessage=e=>{if(pyRunnerTimeout)clearTimeout(pyRunnerTimeout);pyRunnerTimeout=null;const text=(e.data.ok?'Execution completed.\n':'Execution error.\n')+e.data.output;state.labRuns[lab.id]=text;save();const panel=document.getElementById('pythonOutput');if(panel)panel.textContent=text;stopPythonWorkerOnly()};pyRunner.onerror=e=>{const text='Python runtime unavailable. Confirm an internet connection or copy the code to a local Jupyter notebook. '+e.message;state.labRuns[lab.id]=text;save();const panel=document.getElementById('pythonOutput');if(panel)panel.textContent=text;stopPythonWorkerOnly()};pyRunnerTimeout=setTimeout(()=>{const msg='Execution timed out after 90 seconds. Run heavy work in a local notebook.';state.labRuns[lab.id]=msg;save();stopPythonWorkerOnly();const panel=document.getElementById('pythonOutput');if(panel)panel.textContent=msg},90000);pyRunner.postMessage({code});
 }catch(e){if(out)out.textContent='Web Workers could not start: '+e.message+' . Use local Python or Jupyter.'}
}
function stopPythonWorkerOnly(){if(pyRunner){pyRunner.terminate();pyRunner=null}if(pyRunnerTimeout){clearTimeout(pyRunnerTimeout);pyRunnerTimeout=null}}
function isDevMode(){try{const h=window.location.hash;const origin=window.location.origin;return (origin==='null'||origin.includes('localhost')||origin.includes('127.0.0.1')||h.includes('rebuild.brand'))}catch(e){return false}}
function devRebuildBtnVisibility(){const btn=document.getElementById('devRebuildBtn');if(btn)btn.style.display=isDevMode()?'inline-flex':'none'}
function doClick(action,el){const id=el.dataset.day,week=Number(el.dataset.week);switch(action){
case 'toggle-sidebar':document.getElementById('sidebar').classList.toggle('open');document.getElementById('overlay').classList.toggle('open');break;
case 'nav':navigate(el.dataset.route);break;
case 'open-day':navigate('learn',{day:id,tab:el.dataset.tab||'overview'});break;
case 'open-week':navigate('learn',{week});break;
case 'open-project':ui.projectOpen=week;navigate('projects',{project:week});break;
case 'flow':ui.flow=el.dataset.id;render();break;
case 'lesson-tab':ui.tab=el.dataset.tab;render();break;
case 'mark-day':markLessonDirect(id);break;
case 'quiz-choice':{if(quizLimitReached(id))return;const question=Number(el.dataset.question),choice=Number(el.dataset.choice);changeDay(id,d=>{d.quizDraft=d.quizDraft||{};d.quizDraft[question]=choice},null);break}
case 'quiz-submit':quizSubmit(id);break;
case 'quiz-retake':{if(quizLimitReached(id))return;ui.tab='quiz';changeDay(id,d=>d.quizDraft={},null);break}
case 'quiz-clear':quizClear(id);break;
case 'code-mode':ui.codeMode=el.dataset.mode;render();break;
case 'select-toggle':{const root=el.closest('.smart-select'),menu=root?.querySelector('.smart-menu');if(!menu)return;const opening=menu.hidden;closeSmartSelects(root);menu.hidden=!opening;root.classList.toggle('open',opening);root.querySelector('.smart-trigger')?.setAttribute('aria-expanded',String(opening));if(opening)menu.querySelector('[aria-selected="true"]')?.focus();break}
case 'select-value':{const key=el.dataset.key,value=el.dataset.value;if(key==='custom-formula'||key==='custom-week'){if(key==='custom-formula')ui.customFormula=value;else ui.customWeek=Number(value);const root=el.closest('.smart-select');root.querySelector('.smart-trigger span').textContent=el.textContent.trim();root.querySelectorAll('[role="option"]').forEach(o=>{o.setAttribute('aria-selected',String(o===el));o.classList.toggle('selected',o===el)});closeSmartSelects()}else{closeSmartSelects();selectChoice(key,value)}break}
case 'bookmark':changeDay(id,s=>s.bookmarked=!s.bookmarked);break;
case 'prev-day':advanceDay(id,-1);break;
case 'next-day':advanceDay(id,1);break;
case 'answer':break; // v1 quiz handler kept solely for import compatibility
case 'copy-code':copyText(fullCodeForDay(id,el.dataset.mode||ui.codeMode||'starter'));break;
case 'add-minutes':{const m=Number(el.dataset.minutes)||0;state.minutes[id]=(state.minutes[id]||0)+m;recordActivity('study-time',id);save();render();const loggedDay=ALL_DAYS.find(x=>x.id===id);toast(`${m} minutes logged${loggedDay?` · ${loggedDay.title}`:''}`);break}
case 'lab-select':ui.lab=el.dataset.lab;ui.labView='explore';window.currentLabResult=null;render();break;
case 'lab-view':ui.labView=el.dataset.view;render();break;
case 'lab-create':ui.customEditing=null;ui.customFormula='linear';ui.customWeek=1;ui.lab='creator';render();break;
case 'lab-edit':{const l=currentLab();if(!l.id.startsWith('custom-'))return;ui.customEditing=l.id;ui.customFormula=l.formula;ui.customWeek=l.week;ui.lab='creator';render();break}
case 'lab-delete':{const l=currentLab();if(!l.id.startsWith('custom-')||!confirm('Delete this custom lab and its saved code?'))return;state.customLabs=state.customLabs.filter(x=>x.id!==l.id);delete state.labCode[l.id];delete state.labRuns[l.id];delete state.labs[l.id];ui.lab='tensor';save();render();toast('Custom lab deleted');break}
case 'lab-reset':resetLab();break;
case 'lab-copy-json':{if(window.currentLabResult?.lab!==currentLab().id)updateLabOutput();copyText(JSON.stringify(window.currentLabResult||{lab:currentLab().id,unavailable:true},null,2));break}
case 'lab-copy-python':copyText(defaultLabCode(currentLab()));break;
case 'lab-run-python':runPythonCell();break;
case 'lab-stop-python':stopPython();break;
case 'lab-restore-python':{const l=currentLab();delete state.labCode[l.id];save();render();break}
case 'lab-copy-py-output':copyText(state.labRuns[currentLab().id]||'No Python output yet');break;
case 'project-expand':ui.projectOpen=ui.projectOpen===week?0:week;render();break;
case 'rate-skill':state.readiness[el.dataset.skill]=Number(el.dataset.rating);save();render();break;
case 'readiness-plan':ui.readinessPlan=true;render();break;
case 'dev-rebuild':{toast('Rebuild triggered. Running python3 builder/build.py...');setTimeout(()=>{window.location.hash='#rebuild.brand';window.location.reload()},300);break}
case 'theme':setTheme(state.theme==='dark'?'light':'dark');break;
case 'set-theme':setTheme(el.dataset.theme);break;
case 'timer-toggle':focusToggle();break;
case 'timer-reset':focusReset();break;
case 'preview-sound':playCompletionSound();break;
case 'export':exportState();break;
case 'import':document.getElementById('importFile').click();break;
case 'reset':if(confirm('Delete all local learning progress, notes, quiz history, custom labs, outputs and projects? Export a backup first.')){const oldTheme=state.theme;stopPythonWorkerOnly();state=defaultState();state.theme=oldTheme;focusReset();save();render();toast('Learning progress reset')}break;
default:console.warn('Unknown action',action)} }
document.addEventListener('click',ev=>{const a=ev.target.closest('[data-action]');if(!a)return;if(a.tagName==='INPUT'&&a.type==='checkbox')return;ev.preventDefault();doClick(a.dataset.action,a)});
document.addEventListener('change',ev=>{const el=ev.target,act=el.dataset.action;
if(el.dataset.change==='week'){ui.week=Number(el.value);if(ui.route==='learn')ui.day=WEEKS[ui.week-1].days[0].id;render();return}
if(el.type==='checkbox')switch(act){case 'learned':changeDay(el.dataset.day,s=>s.learned=el.checked,'learned');return;case 'practice-step':changeDay(el.dataset.day,s=>s.steps[Number(el.dataset.index)]=el.checked,'practice');return;case 'reading-done':changeDay(el.dataset.day,s=>{s.readingsStatus=s.readingsStatus||{};s.readingsStatus[el.dataset.index]=el.checked},'reference');return;case 'project-task':{const p=projectState('w'+el.dataset.week);p.tasks[Number(el.dataset.index)]=el.checked;recordActivity('project');save();render();if(p.tasks.every(Boolean))toast('Project checklist complete');return}case 'lab-done':state.labs[el.dataset.lab]=el.checked;recordActivity('lab');save();render();return;case 'focus-sound':state.settings.focusSound=el.checked;save();toast('Sound preference saved');return;default:break}
if(el.dataset.input==='lab'){state.labValues[el.dataset.key]=el.value;save();updateLabOutput()}if(el.dataset.change==='focus-minutes'){const n=Math.round(Number(el.value));if(!Number.isFinite(n)||n<1||n>180){el.value=state.settings.focusMinutes;toast('Choose a number between 1 and 180');return}state.settings.focusMinutes=n;if(!timer.running)focusReset();save();toast('Focus duration saved') }});
document.addEventListener('input',ev=>{const el=ev.target;switch(el.dataset.input){case 'note':dayState(el.dataset.day).notes=el.value.slice(0,12000);save();break;
case 'project-evidence':projectState('w'+el.dataset.week).evidence=el.value.slice(0,1200);save();break;
case 'project-note':projectState('w'+el.dataset.week).notes=el.value.slice(0,12000);save();break;
case 'lab-code':state.labCode[el.dataset.lab]=el.value.slice(0,20000);save();break;
case 'lab':state.labValues[el.dataset.key]=el.value;if(el.id&&el.id.startsWith('lab-')){const target=document.getElementById('v-'+el.dataset.key);if(target)target.textContent=el.value}save();updateLabOutput();break;
case 'search':ui.search=el.value;document.getElementById('searchResults').innerHTML=renderSearchResults();iconRefresh();break;
default:break}});
document.addEventListener('submit',ev=>{if(ev.target.id==='customLabForm'){ev.preventDefault();saveCustomLab(ev.target)}});
document.addEventListener('pointerdown',ev=>{if(!ev.target.closest('.smart-select'))closeSmartSelects()});
document.addEventListener('keydown',ev=>{const root=ev.target.closest('.smart-select');if(!root)return;const menu=root.querySelector('.smart-menu'),options=[...root.querySelectorAll('[role="option"]')],index=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(ev.key)){ev.preventDefault();if(menu.hidden){const trigger=root.querySelector('.smart-trigger');trigger.click()}else options[(index+(ev.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus()}if(ev.key==='Escape'){closeSmartSelects();root.querySelector('.smart-trigger')?.focus()}if(ev.key==='Enter'&&document.activeElement?.getAttribute('role')==='option'){ev.preventDefault();document.activeElement.click()}});
document.getElementById('overlay').addEventListener('click',()=>{document.getElementById('overlay').classList.remove('open');document.getElementById('sidebar').classList.remove('open')});
document.getElementById('importFile').addEventListener('change',async ev=>{const f=ev.target.files?.[0];if(!f)return;try{if(f.size>4_000_000)throw new Error('Backup is too large (4 MB maximum)');const parsed=JSON.parse(await f.text());if(!validateImport(parsed))throw new Error('This is not a supported FORM / AI progress export');if(!confirm('Replace current progress with this backup? Export your current data first.'))return;state=normalizeState(parsed);applyTheme();save();navigate('dashboard');toast('Progress restored from backup')}catch(err){alert('Import failed: '+err.message)}finally{ev.target.value=''}});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();navigate('search');document.getElementById('course-search')?.focus()}if(ev.key==='Escape'){document.getElementById('overlay').classList.remove('open');document.getElementById('sidebar').classList.remove('open')}});
